import 'package:flutter/widgets.dart';
import 'package:flutter_svg/flutter_svg.dart';

/// Authentic Google Weather icons from WeatherMaster mirroring Sharva's WeatherIcon.
class WeatherIcon extends StatelessWidget {
  final String name;
  final double size;
  final bool? isDay;
  final Widget? placeholder;
  final VoidCallback? onTap;

  const WeatherIcon({
    super.key,
    required this.name,
    this.size = 24,
    this.isDay,
    this.placeholder,
    this.onTap,
  });

  @override
  Widget build(BuildContext context) {
    final hour = DateTime.now().hour;
    final isNightNow = hour < 6 || hour >= 19;
    final effectiveDay = isDay ?? !isNightNow;
    final defaultFallback = effectiveDay ? 'clear_day' : 'clear_night';

    String key = name.trim().toLowerCase();
    if (key.isEmpty) {
      key = defaultFallback;
    }

    // Automatically map day/night variants to match the active day/night state
    if (!effectiveDay) {
      // Night time: ensure night variant is selected
      if (key == 'clear_day' || key == 'clear' || key == 'sunny') {
        key = 'clear_night';
      } else if (key == 'mostly_clear_day' || key == 'mostly_clear') {
        key = 'mostly_clear_night';
      } else if (key == 'partly_cloudy_day' || key == 'partly_cloudy' || key == 'cloudy') {
        key = 'partly_cloudy_night';
      } else if (key == 'light_rain_day' || key == 'light_rain') {
        key = 'light_rain_night';
      } else if (key == 'light_snow_day' || key == 'light_snow') {
        key = 'light_snow_night';
      } else if (key.endsWith('_day')) {
        final nightKey = key.replaceAll('_day', '_night');
        if (_weatherSvgMap.containsKey(nightKey)) {
          key = nightKey;
        }
      }
    } else {
      // Day time: ensure day variant is selected
      if (key == 'clear_night' || key == 'clear' || key == 'sunny') {
        key = 'clear_day';
      } else if (key == 'mostly_clear_night' || key == 'mostly_clear') {
        key = 'mostly_clear_day';
      } else if (key == 'partly_cloudy_night' || key == 'partly_cloudy' || key == 'cloudy') {
        key = 'partly_cloudy_day';
      } else if (key == 'light_rain_night' || key == 'light_rain') {
        key = 'light_rain_day';
      } else if (key == 'light_snow_night' || key == 'light_snow') {
        key = 'light_snow_day';
      } else if (key.endsWith('_night')) {
        final dayKey = key.replaceAll('_night', '_day');
        if (_weatherSvgMap.containsKey(dayKey)) {
          key = dayKey;
        }
      }
    }

    final svgString = _weatherSvgMap[key] ??
        _weatherSvgMap[defaultFallback] ??
        _weatherSvgMap['clear_day']!;

    final svgWidget = SvgPicture.string(
      svgString,
      width: size,
      height: size,
      placeholderBuilder: placeholder != null ? (_) => placeholder! : null,
    );

    if (onTap != null) {
      return MouseRegion(
        cursor: SystemMouseCursors.click,
        child: GestureDetector(
          onTap: onTap,
          behavior: HitTestBehavior.opaque,
          child: svgWidget,
        ),
      );
    }

    return svgWidget;
  }
}

